mapper.select:
SELECT * FROM (
  SELECT t.*, ROWNUM rn FROM (
    SELECT l.ID, l.APPLICANT, NVL(l.REASON, '无') REASON, TO_CHAR(l.START_DATE, 'yyyy-mm-dd') START_DATE,
           d.DEPT_NAME
    FROM OA_LEAVE l, OA_DEPT d
    WHERE l.DEPT_ID = d.ID(+)
    ORDER BY l.CREATED DESC
  ) t WHERE ROWNUM <= #{end}
) WHERE rn > #{start}
